insert into public.boards (code,name,members_only,admin_only_write) values ('audit','행정사무감사',false,true) on conflict (code) do nothing;
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2025.11.11. 화요일] 기획조정실, 경기연구원 — 기획재정위원회 2025년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제11대 경기도의회 기획재정위원회</b> · 2025년도 행정사무감사(2025. 11. 07. ~ 2025. 11. 20.)<br><a href="https://grilu.kr/gri/audit/15289.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=15289" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">2025년도 경기도의회 행정사무감사 기획재정위원회 회의록 경기도의회사무처 피감사기관: 기획조정실, 경기연구원 일 시: 2025년 11월 11일(화) 장 소: 기획재정위원회 회의실 (10시00분 감사개시) ○ 위원장 조성환 의석을 정돈해 주시기 바랍니다. 계속해서 지방자치법 제49조 및 동법 시행령 제41조, 경기도의회 행정사무감사 및 조사에 관한 조례에 따라 어제에 이어 기획조정실, 경기연구원 소관에 관한 2025년도 행정사무감사를 시작하겠습니다. 감사위원 여러분 그리고 공직자 여러분! 안녕하십니까? 기획재정위원회 위원장 조성환입니다. 어제에 이어 감사에 임해 주시는 위원님들과 허승범 기획조정실장님 그리고 경기도의 싱크탱크인 우리 경기연구원 정책개발과 도정개발에 힘쓰고 계시는데 우리 강성천 원장님과 관계공직자 여러분께 감사를 드립니다. 오늘 이 자리에는 어제에 이어서 언론인이신 전국매일신문의 한영민 기자님, 일간경기의 김인창 기자님께서 취재 중이십니다. 감사말씀드립니다. 그러면 감사 시작에 앞서 새로 출석하신 경기연구원장 및 관계자분들의 증인선서가 있겠습니다. 감사를 받는 강성천 경기연구원장과 각 부서장께서는 증인의 자격으로 소관 업무보고와 질의 답변에 앞서 선서를 하셔야 합니다. 선서를 하는 이유는 경기도의회가 2025년도 행정사무감사를 실시함에 있어 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위함입니다. 만약 증인이 허위증언을 한 때에는 지방자치법 제49조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조 규정에 의해 고발될 수 있으며 정당한 사유 없이 선서 또는 증언을 거부한 때에는 동법 규정 및 동 조례 제31조에 의하여 500만 원 이하의 과태료가 부과될 수 있음을 알려드립니다. 아울러 형사소송법 제148조 근친자의 형사책임과 증언 거부 또는 제149조 업무상비밀과 증언거부에 해당하는 때에는 선서와 증언 그리고 서류제출을 거부할 수 있음을 함께 알려드립니다. 그러면 증인 출석 여부를 확인하겠습니다. 새로 출석하신 피감사기관의 증인들께서는 모두 자리에서 일어나 주시기 바랍니다. 강성천 경기연구원장님 나오셨습니까? ○ 경기연구원장 강성천 네. ○ 위원장 조성환 박경철 경기연구원 부원장님 나오셨습니까? ○ 경기연구원부원장 박경철 네. ○ 위원장 조성환 정대영 연구기획실장 나오셨습니까? ○ 경기연구원연구기획실장 정대영 네. ○ 위원장 조성환 유정균 인구사회연구실장 나오셨습…</p>','경기도의회',false,'{"legacy_id": "audit-15289", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=15289", "page": "https://grilu.kr/gri/audit/15289.html"}'::jsonb,'2025-11-11'::date,'2025-11-11'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-15289');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2024.11.18. 월요일] 기획재정위원회 전 소관부서(기획조정실, 감사위원회, 도민권익위원회, 경기연구원) — 기획재정위원회 2024년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제11대 경기도의회 기획재정위원회</b> · 2024년도 행정사무감사(2024. 11. 08. ~ 2024. 11. 21.)<br><a href="https://grilu.kr/gri/audit/14894.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=14894" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">2024년도 행정사무감사 기획재정위원회 회의록 경기도의회사무처 피감사기관: 기획재정위원회 전 소관부서(기획조정실, 감사위원회, 도민권익위원회, 경기연구원) 일 시: 2024년 11월 18일(월) 장 소: 기획재정위원회 회의실 (10시17분 감사개시) ○ 위원장 조성환 의석을 정돈해 주시기 바랍니다. 지금부터 지방자치법 제49조 및 동법 시행령 제41조, 경기도의회 행정사무감사 및 조사에 관한 조례에 따라 기획조정실, 감사위원회, 도민권익위원회, 경기연구원과 경기주택도시공사 등 8개 기관의 소관 사항에 대하여 종합감사를 시작하겠습니다. 감사위원 여러분 그리고 관계공직자 여러분! 안녕하십니까? 기획재정위원회 위원장 조성환입니다. 지난 11일부터 기획조정실을 시작으로 우리 위원회 소관 기관에 대한 행정사무감사 및 현지확인을 15일에 마쳤습니다. 여러 불편을 감수하시면서 감사에 적극 임해 주신 우리 위원님들의 노고에 감사드리고 행정사무감사에 성실히 협조해 주신 수감기관 공직자분들께도 격려의 말씀을 전합니다. 오늘 실시하는 종합감사는 지난주에 실시했던 소관 실국별 감사내용을 다시 한번 종합적으로 점검ㆍ검토하고 정책적 개선방안을 모색하는 데 그 취지가 있습니다. 감사위원님들께서는 이 점 양지하여 주시고 수감기관에서도 적극 협조하여 주시기 바랍니다. 특별히 오늘은 공공기관의 기관장분들께서도 출석을 해 주셨는데요. 저희가 공공기관담당관실을 감사하면서 경기도의 도정과 우리 공공기관들의 사업 방향이 일치할 필요가 있고 그다음에 여러 가지 재정적인, 예산적인 부분이나 소관 업무에 대한 감사 부분에 있어서 같이 의논할 필요가 있다라고 판단이 되어서 우리 위원님들과 협의한 끝에 이렇게 출석을 하게 됐습니다. 바쁜 일정에 참석해 주셔서 감사의 말씀을 드립니다. 오늘 이 자리에는 우리 위원회의 행정사무감사 활동을 모니터링하기 위해서 수원에서 오신 조미현 님께서 방청하고 계십니다. 또한 언론인이신 전국매일신문 한영민 기자님, 일간경기 김인찬 기자님, 아시아타임즈 임성민 기자님, 천지일보 이성애 기자님께서 취재 중이십니다. 기획재정위원회를 대표하여 감사의 말씀을 드립니다. 질의에 앞서 새로 출석하신 분들에 대한 증인선서가 있겠습니다. 지난 11월 14일 우리 위원회 제2차 회의에서 좀 더 심도 있고 내실 있는 감사를 위한 추가 증인 출석요구 의결이 있었습니다. 금일 새롭게 출석요구받은 증인은 경기주택도시공사 사장을 포함한 공공기관장 및 관계…</p>','경기도의회',false,'{"legacy_id": "audit-14894", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=14894", "page": "https://grilu.kr/gri/audit/14894.html"}'::jsonb,'2024-11-18'::date,'2024-11-18'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-14894');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2024.11.12. 화요일] 감사위원회, 도민권익위원회, 경기연구원 — 기획재정위원회 2024년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제11대 경기도의회 기획재정위원회</b> · 2024년도 행정사무감사(2024. 11. 08. ~ 2024. 11. 21.)<br><a href="https://grilu.kr/gri/audit/14879.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=14879" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">2024년도 행정사무감사 기획재정위원회 회의록 경기도의회사무처 피감사기관: 감사위원회, 도민권익위원회, 경기연구원 일 시: 2024년 11월 12일(화) 장 소: 기획재정위원회 회의실 (10시17분 감사개시) ○ 위원장 조성환 의석을 정돈해 주시기 바랍니다. 지금부터 지방자치법 제49조 및 동법 시행령 제41조, 경기도의회 행정사무감사 및 조사에 관한 조례에 따라 감사위원회 및 도민권익위원회 소관에 대한 2024년도 행정사무감사를 시작하겠습니다. 감사위원 여러분 그리고 공직자 여러분! 안녕하십니까? 기획재정위원회 위원장 조성환입니다. 어제에 이어 계속해서 행정사무감사를 위해 수고해 주시는 위원님들께 감사드립니다. 공정하고 투명한 감사 운영으로 청렴한 경기도를 만들기 위해서 애쓰시는 안상섭 감사위원장, 장진수 도민권익위원장을 비롯한 관계공직자 여러분께도 감사의 말씀드립니다. 그러면 오늘은 위원회 감사일정에 따라 감사위원회와 도민권익위원회 소관에 대한 2024년도 행정사무감사를 시작하겠습니다. 오늘 이 자리에는 우리 위원회의 행정사무감사 활동을 모니터링하기 위해서 수원에서 조미현 님께서 수고해 주시고 특히 경상북도의회 정진오 서기관님께서 수고해 주십니다. 환영합니다. 또한 언론인이신 스카이데일리 강재규 기자님께서 취재 중이십니다. 기획재정위원회를 대표해서 감사 말씀드립니다. 공직자 여러분께서도 잘 아시는 바와 같이 지방의회 행정사무감사는 집행기관의 행정사무 전반에 관한 실태를 파악하여 잘못된 점을 시정ㆍ개선하고 나아가 2025년도 예산안 심사에 반영함은 물론 도민의 삶의 질 향상에 기여하는 것이 그 목적인 만큼 매우 중요한 의미가 있습니다. 따라서 감사에 임하는 집행기관 공직자분들께서도 본 위원회가 이번 행정사무감사를 통해 얻고자 하는 소기의 목적이 달성될 수 있도록 감사에 충실히 임해 주시기를 바랍니다. 그러면 증인선서가 있겠습니다. 감사를 받는 안상섭 감사위원장과 각 부서장 및 장진수 도민권익위원장은 증인의 자격으로 소관 업무보고와 질의 답변에 앞서 선서를 하셔야 합니다. 선서를 하는 이유는 경기도의회가 2024년도 행정사무감사를 실시함에 있어 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위함입니다. 만약 증인이 허위증언을 한 때에는 지방자치법 제49조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조 규정에 의하여 고발될 수 있으며 정당한 사유 없이 선서 또는 증언을 거부한…</p>','경기도의회',false,'{"legacy_id": "audit-14879", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=14879", "page": "https://grilu.kr/gri/audit/14879.html"}'::jsonb,'2024-11-12'::date,'2024-11-12'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-14879');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2022.11.09. 수요일] 경기연구원 — 기획재정위원회 2022년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제11대 경기도의회 기획재정위원회</b> · 2022년도 행정사무감사(2022. 11. 04. ~ 2022. 11. 17.)<br><a href="https://grilu.kr/gri/audit/13928.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=13928" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">2022년도 행정사무감사 기획재정위원회 회의록 경기도의회사무처 피감사기관: 경기연구원 일 시: 2022년 11월 9일(수) 장 소: 기획재정위원회 회의실 (16시26분 감사개시) ○ 위원장 지미연 의석을 정돈하여 주시기 바랍니다. 성원이 되었으므로 감사를 속개하겠습니다. 지금부터 지방자치법 제49조, 동법 시행령 제43조제1항과 경기도의회 행정사무감사 및 조사에 관한 조례 제2조 규정에 의하여 경기연구원 소관에 대한 2022년도 행정사무감사를 시작하겠습니다. 위원님 여러분 그리고 관계자 여러분! 안녕하십니까? 기획재정위원회 감사위원장 지미연 위원입니다. 감사관 소관에 이어 계속해서 수고하시는 위원님들과 경기도의 싱크탱크로서 도정 선도를 위한 정책연구에 애쓰시는 송미영 연구부원장을 비롯한 관계자 여러분의 노고에 감사와 격려를 표합니다. 그럼 우리 위원회 감사일정에 따라 경기연구원에 대한 2022년도 행정사무감사를 실시하겠습니다. 경기연구원 관계자 여러분께서 잘 아시는 바와 같이 지방의회 행정사무감사는 집행기관의 행정사무 전반에 관한 실태를 파악하고 나아가 2023년도 예산안 심사에 반영함은 물론 도민의 삶의 질 향상에 기여하는 것이 그 목적인 만큼 매우 중요한 의미가 있습니다. 따라서 감사에 임하는 경기연구원 관계자 여러분께서도 본 위원회가 이번 행정사무감사를 통해 얻고자 하는 소기의 목적이 달성될 수 있도록 감사에 충실히 임해 주시기 당부드립니다. 그러면 감사를 하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 송미영 연구부원장과 각 본부장, 실장 등은 증인의 자격으로 소관 업무를 보고하고 질의에 답변하기에 앞서 선서를 하셔야 합니다. 선서를 하는 이유는 경기도의회가 2022년도 행정사무감사를 실시함에 있어 증인으로부터 양심에 따라 숨김 없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 한 때에는 지방자치법 제49조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조의 규정에 의하여 고발될 수 있으며 증언을 거부한 때에는 동법 규정 및 동 조례 제31조에 의하여 500만 원 이하의 과태료가 부과될 수 있음을 알려드립니다. 아울러 형사소송법 제148조 근친자의 형사책임과 증언 거부 또는 제149조 업무상 비밀과 증언 거부에 해당하는 때에는 선서와 증언 그리고 서류 제출을 거부할 수 있음을 함께 알려드립니다. 참고로 경기연구원장은 현재 공석이어서 송미영 연구부원장이 원장의…</p>','경기도의회',false,'{"legacy_id": "audit-13928", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=13928", "page": "https://grilu.kr/gri/audit/13928.html"}'::jsonb,'2022-11-09'::date,'2022-11-09'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-13928');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2021.11.09. 화요일] 경기연구원 — 기획재정위원회 2021년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제10대 경기도의회 기획재정위원회</b> · 2021년도 행정사무감사(2021. 11. 05. ~ 2021. 11. 18.)<br><a href="https://grilu.kr/gri/audit/13486.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=13486" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">2021년도 행정사무감사 기획재정위원회 회의록 경기도의회사무처 피감사기관: 경기연구원 일 시: 2021년 11월 9일(화) 장 소: 기획재정위원회 회의실 (15시31분 감사개시) ○ 위원장 심규순 의석을 정돈하여 주시기 바랍니다. 지금부터 지방자치법 제41조, 동법 시행령 제39조와 경기도의회 행정사무감사 및 조사에 관한 조례 제2조의 규정에 의하여 경기연구원에 대한 2021년도 행정사무감사를 시작하겠습니다. 허성관 경기연구원 이사장을 비롯한 관계자 여러분! 안녕하십니까? 기획재정위원장 심규순입니다. 지금부터 우리 위원회 감사일정에 따라 경기연구원에 대한 행정사무감사를 실시하겠습니다. 여러분들께서도 잘 아시는 바와 같이 지방의회 행정사무감사는 집행기관의 행정사무 전반에 관한 실태를 정확히 파악하는 한편 나아가 2022년도 예산안 심사에 반영하고 도정 실태를 파악하여 도민의 삶과 질 향상에 기여하고자 함이 그 목적인 만큼 매우 중요한 의미가 있다고 하겠습니다. 따라서 감사에 임하는 관계자 여러분께서도 본 위원회가 이번 행정사무감사를 통해 얻고자 하는 소기의 목적이 달성될 수 있도록 감사에 충실히 임해 주시기를 당부드립니다. 그러면 감사를 하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 허성관 경기연구원 이사장과 각 본부장, 실장 등은 증인의 자격으로 소관 업무를 보고하고 질의에 답변하기 전에 선서를 하여야 합니다. 선서를 하는 이유는 경기도의회가 2021년도 행정사무감사를 실시함에 있어 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 한 때는 지방자치법 제41조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조 규정에 의하여 고발될 수 있으며 증언 또는 진술을 거부한 때에는 동법 규정에 의하여 500만 원 이하의 과태료가 부과될 수 있음을 알려드립니다. 아울러 형사소송법 제148조 근친자의 형사책임과 증언 거부 또는 제149조 업무상비밀과 증언 거부에 해당되는 때에는 선서와 증언 그리고 서류제출을 거부할 수 있음을 함께 알려드립니다. 그러면 먼저 증인 출석여부를 확인하겠습니다. 피감사기관의 증인들께서는 모두 자리에서 일어서 주시기 바랍니다. (일동기립) 허성관 경기연구원 이사장 나오셨습니까? ○ 경기연구원장직무대행 허성관 네. ○ 위원장 심규순 송미영 연구부원장 나오셨습니까? ○ 연구부원장 송미영 네. ○ 위원장 심규순 장형철 경영부원장…</p>','경기도의회',false,'{"legacy_id": "audit-13486", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=13486", "page": "https://grilu.kr/gri/audit/13486.html"}'::jsonb,'2021-11-09'::date,'2021-11-09'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-13486');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2020.11.09. 월요일] 경기연구원 — 기획재정위원회 2020년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제10대 경기도의회 기획재정위원회</b> · 2020년도 행정사무감사(2020. 11. 06. ~ 2020. 11. 19.)<br><a href="https://grilu.kr/gri/audit/12030.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=12030" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">2020년도 행정사무감사 기획재정위원회 회의록 경기도의회사무처 피감사기관: 경기연구원 일 시: 2020년 11월 9일(월) 장 소: 기획재정위원회 회의실 (16시26분 감사개시) ○ 심규순 위원장 좌석을 정돈하여 주시기 바랍니다. 지금부터 지방자치법 제41조, 동법 시행령 제39조와 경기도의회 행정사무감사 및 조사에 관한 조례 제2조의 규정에 따라 경기연구원에 대한 2020년도 행정사무감사를 시작하겠습니다. 이한주 경기연구원장을 비롯한 임직원 여러분! 안녕하십니까? 기획재정위원회 감사위원장 심규순 위원입니다. 지금부터 우리 위원회 감사일정에 따라 경기연구원에 대한 행정사무감사를 실시하겠습니다. 연구원 임직원 여러분께서도 잘 아시는 바와 같이 지방의회의 행정사무감사는 집행부의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 나아가 2021년도 예산안 심사자료 및 정보를 획득하여 도민의 삶의 질 향상에 기여하고자 함이 그 목적인 만큼 매우 중요한 의미가 있다고 하겠습니다. 따라서 감사에 임하는 집행부 공직자 여러분께서도 본 위원회가 이번 행정사무감사를 통해 얻고자 하는 소기의 목적이 달성될 수 있도록 감사에 충실히 임해 주시기를 당부드립니다. 그러면 감사를 하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 경기연구원장과 각 본부장, 실장 등은 증인의 자격으로 업무소관을 보고하고 질의에 답변하기에 앞서 선서를 하셔야 합니다. 증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 경기도의회가 2020년도 행정사무감사를 실시함에 있어 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 할 때는 지방자치법 제41조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조의 규정에 의하여 고발될 수 있으며 증언 또는 진술을 거부한 때에는 동법 규정에 의하여 500만 원 이하의 과태료가 부과됨을 알려드립니다. 그러면 먼저 증인들께서는 자리에서 모두 일어나 주시기 바랍니다. 경기연구원장 나오셨습니까? ○ 경기연구원장 이한주 네. ○ 심규순 위원장 경기부원장 경영부원장 겸임 나왔습니까? ○ 연구부원장 송미영 네. ○ 심규순 위원장 경기기획본부장 나왔습니까? ○ 연구기획본부장 봉인식 연구기획본부장 나왔습니다. ○ 심규순 위원장 아, 그럽니까? 네. 균형발전본부장 나왔습니까? ○ 균형발전본부장 김동성 네, 나왔습니다. ○ 심규순 위원장 북부연구센터…</p>','경기도의회',false,'{"legacy_id": "audit-12030", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=12030", "page": "https://grilu.kr/gri/audit/12030.html"}'::jsonb,'2020-11-09'::date,'2020-11-09'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-12030');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2019.11.12. 화요일] 경기연구원 — 기획재정위원회 2019년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제10대 경기도의회 기획재정위원회</b> · 2019년도 행정사무감사(2019. 11. 11. ~ 2019. 11. 22.)<br><a href="https://grilu.kr/gri/audit/11569.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=11569" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">2019년도 행정사무감사 기획재정위원회 회의록 경기도의회사무처 피감사기관: 경기연구원 일 시: 2019년 11월 12일(화) 장 소: 기획재정위원회 회의실 (15시56분 감사개시) ○ 위원장 정대운 좌석을 정돈해 주시기 바랍니다. 지금부터 지방자치법 제41조, 동법 시행령 제39조와 경기도의회 행정사무감사 및 조사에 관한 조례 제2조의 규정에 의하여 경기연구원에 대한 2019년도 행정사무감사를 시작하겠습니다. 위원님 여러분 그리고 이한주 경기연구원장을 비롯한 공직자 여러분! 안녕하십니까? 기획재정위원회 감사위원장 정대운 위원입니다. 오늘은 우리 위원회 감사일정에 따라 경기연구원에 대한 행정사무감사를 실시하겠습니다. 잘 아시는 바와 같이 지방의회 행정사무감사는 집행부의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 나아가 2020년도 예산안 심사자료 및 정보를 획득하여 도민의 삶의 질 향상에 기여하고자 함이 그 목적인 만큼 매우 중요한 의미가 있다고 하겠습니다. 따라서 감사위원 여러분께서는 도민을 대표하여 집행부 도정 전반에 대해 감사하는 것이므로 명확한 사실에 근거하여 핵심적이고 심도 있는 감사를 통해 소기의 성과를 거둘 수 있는 뜻깊은 시간이 되기를 기대합니다. 아울러 감사에 임하는 집행부 공직자 여러분께서도 본 위원회가 이번 행정사무감사를 통해 얻고자 하는 소기의 목적이 달성될 수 있도록 감사에 충실히 임해 주시길 당부드립니다. 그러면 감사를 하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 원장, 부원장과 본부장, 실장, 부장은 증인의 자격으로 소관 업무를 보고하고 질의에 답변하기에 앞서 선서를 해야 합니다. 증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 경기도의회가 2019년도 행정사무감사를 실시함에 있어 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 할 때에는 지방자치법 제41조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조의 규정에 의하여 고발될 수 있으며 증언 또는 진술을 거부할 때에는 동법 규정에 의하여 500만 원 이하의 과태료가 부과될 수 있음을 알려드립니다. 그러면 먼저 증인출석 여부를 확인하겠습니다. 피감사기관의 증인들께서는 모두 자리에서 일어나 주시기 바랍니다. 경기연구원장 나왔습니까? ○ 경기연구원장 이한주 네, 나왔습니다. ○ 위원장 정대운 연구부원장 나왔습니까? ○ 연구부원…</p>','경기도의회',false,'{"legacy_id": "audit-11569", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=11569", "page": "https://grilu.kr/gri/audit/11569.html"}'::jsonb,'2019-11-12'::date,'2019-11-12'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-11569');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2018.11.13. 화요일] 경기연구원 — 기획재정위원회 2018년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제10대 경기도의회 기획재정위원회</b> · 2018년도 행정사무감사(2018. 11. 12. ~ 2018. 11. 23.)<br><a href="https://grilu.kr/gri/audit/10849.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=10849" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">2018년도 행정사무감사 기획재정위원회 회의록 경기도의회사무처 피감사기관 : 경기연구원 일 시 : 2018년 11월 13일(화) 장 소 : 기획재정위원회 회의실 (11시40분 감사개시) ○ 위원장 정대운 좌석을 정돈해 주시기 바랍니다. 성원이 되었으므로 지금부터 지방자치법 제41조, 동법 시행령 제39조 및 경기도의회 행정사무감사 및 조사에 관한 조례 제2조의 규정에 의하여 경기연구원에 대한 2018년도 행정사무감사를 시작하겠습니다. 위원 여러분 그리고 경기연구원 원장을 비롯한 임직원 여러분! 안녕하십니까? 경기도의회 기획재정위원회 감사위원장 정대운 위원입니다. 오늘은 우리 위원회 감사일정에 따라 경기연구원에 대한 행정사무감사를 실시하겠습니다. 행정사무감사는 경기도의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 도민 삶의 질 향상에 기여하고자 함이 목적으로 매우 중요한 의미가 있다고 하겠습니다. 오늘은 경기도 정책연구의 산실인 경기연구원의 운영실태를 감사하는 것인 만큼 연구원에 대한 심도 있는 감사활동으로 경기도 전반을 위한 정책대안이 제시될 수 있도록 위원 여러분들의 적극적인 감사활동을 부탁드립니다. 아울러 감사에 임하는 연구원장과 임직원 여러분께서도 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기 바랍니다. 그러면 감사를 시작하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 원장, 부원장 및 본부장, 실장, 부장은 증인의 자격으로 소관 업무를 보고하고 질의에 답변하기에 앞서 먼저 선서를 하셔야 합니다. 증인선서의 취지와 관계 규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2018년도 행정사무감사를 실시함에 있어 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 할 때에는 지방자치법 제41조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조의 규정에 의하여 고발될 수 있습니다. 또한 증언 또는 진술을 거부할 때에는 동법 규정에 의하여 500만 원 이하의 과태료가 부과될 수 있음을 알려드립니다. 그러면 먼저 증인 출석여부를 확인하겠습니다. 증인들께서는 모두 자리에서 일어나 주시기 바랍니다. (일동기립) 경기연구원 원장 나왔습니까? ○ 경기연구원장 이한주 네. ○ 위원장 정대운 부원장 나오셨습니까? ○ 경기연구원부원장 김군수 네. ○ 위원장 정대운 연구기획본부장 나왔습니까? 안 나왔습니까? ○ 연구기획본…</p>','경기도의회',false,'{"legacy_id": "audit-10849", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=10849", "page": "https://grilu.kr/gri/audit/10849.html"}'::jsonb,'2018-11-13'::date,'2018-11-13'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-10849');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2017.11.20. 월요일] 경기연구원 — 기획재정위원회 2017년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제9대 경기도의회 기획재정위원회</b> · 2017년도 행정사무감사(2017. 11. 13. ~ 2017. 11. 24.)<br><a href="https://grilu.kr/gri/audit/10423.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=10423" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">2017년도 행정사무감사 기획재정위원회 회의록 경기도의회사무처 피감사기관 : 경기연구원 일 시 : 2017년 11월 20일(월) 장 소 : 기획재정위원회 회의실 (10시33분 감사개시) ○ 위원장 이재준 좌석을 정돈해 주시기 바랍니다. 성원이 되었으므로 지금부터 지방자치법 제41조, 동법 시행령 제39조 및 경기도의회 행정사무감사 및 조사에 관한 조례 제2조의 규정에 의하여 경기연구원에 대한 2017년도 행정사무감사를 시작하겠습니다. 위원 여러분 그리고 경기연구원 원장 직무대행을 비롯한 임직원 여러분! 안녕하십니까? 경기도의회 기획재정위원회 감사위원장 이재준 위원입니다. 오늘은 우리 위원회 감사일정에 따라 경기연구원에 대한 행정사무감사를 실시하게 되었습니다. 여러분께서도 잘 아시는 바와 같이 우리 의회의 행정사무감사는 경기도의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 도민의 삶의 질 향상에 기여하고자 함이 그 목적이므로 매우 중요한 의미가 있다고 하겠습니다. 오늘은 경기도의 싱크탱크인 경기연구원의 운영실태를 감사하는 것인 만큼 연구원에 대한 심도 있는 감사활동으로 경기도 발전을 위한 정책대안이 제시될 수 있도록 위원 여러분들의 적극적인 감사활동을 부탁드립니다. 아울러 감사에 임하는 임직원 여러분께서도 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기 바랍니다. 그러면 감사를 시작하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 임직원은 증인의 자격으로 소관 업무를 보고하고 질의에 답변하기에 앞서 먼저 선서를 하셔야 합니다. 증인선서의 취지와 관계 규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2017년도 행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 한 때에는 지방자치법 제41조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조의 규정에 의하여 고발될 수 있습니다. 또한 증언 또는 진술을 거부한 때에는 동법 규정에 의하여 500만 원 이하의 과태료가 부과될 수 있음을 알려드립니다. 그러면 먼저 증인 출석여부를 확인하겠습니다. 증인들께서는 모두 자리에서 일어서 주시기 바랍니다. (일동기립) 경기연구원 원장 직무대행 나왔습니까? ○ 경기연구원장직무대행 김군수 네. ○ 위원장 이재준 연구기획본부장 나왔습니까? ○ 연구기획본부장 이정훈 네. ○ 위원장 이재준 경영본부장 나왔…</p>','경기도의회',false,'{"legacy_id": "audit-10423", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=10423", "page": "https://grilu.kr/gri/audit/10423.html"}'::jsonb,'2017-11-20'::date,'2017-11-20'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-10423');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2016.11.07. 월요일] 경기연구원 — 기획재정위원회 2016년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제9대 경기도의회 기획재정위원회</b> · 2016년도 행정사무감사(2016. 11. 02. ~ 2016. 11. 15.)<br><a href="https://grilu.kr/gri/audit/9630.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=9630" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">2016년도 행정사무감사 기획재정위원회 회의록 경기도의회사무처 피감사기관 : 경기연구원 일 시 : 2016년 11월 7일(월) 장 소 : 경기연구원 회의실 (14시02분 감사개시) ○ 위원장 이재준 좌석을 정돈하여 주시기 바랍니다. 성원이 되었으므로 지금부터 지방자치법 제41조, 동법 시행령 제39조 및 경기도의회 행정사무감사 및 조사에 관한 조례 제2조의 규정에 의하여 경기연구원에 대한 2016년도 행정사무감사를 시작하겠습니다. 위원 여러분 그리고 경기연구원장을 비롯한 임직원 여러분! 안녕하십니까? 경기도의회 기획재정위원회 감사위원장 이재준 위원입니다. 오늘은 우리 위원회의 감사일정에 따라 경기연구원에 대한 행정사무감사를 실시하게 되었습니다. 여러분께서도 잘 아시는 바와 같이 우리 의회의 행정사무감사는 경기도의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 도민의 삶의 질 향상에 기여하고자 함이 목적이므로 매우 중요한 의미가 있다고 하겠습니다. 오늘은 경기도의 싱크탱크인 경기연구원의 운영실태를 감사하는 것인 만큼 연구원에 대한 심도 있는 감사활동으로 경기도 발전을 위한 정책대안이 제시될 수 있도록 위원 여러분들의 적극적인 감사활동을 부탁드립니다. 아울러 감사에 임하는 원장과 임직원 여러분께서도 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기 바랍니다. 그러면 감사를 시작하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 원장 및 부원장, 본부장, 실장, 부장은 증인의 자격으로 소관 업무를 보고하고 질의에 답변하기에 앞서 먼저 선서를 하셔야 합니다. 증인선서의 취지와 관계 규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2016년도 행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 한 때에는 지방자치법 제41조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조의 규정에 의하여 고발될 수 있습니다. 또한 증언 또는 진술을 거부한 때에는 동법 규정에 의하여 500만 원 이하의 과태료가 부과될 수 있음을 알려드립니다. 그러면 먼저 증인 출석여부를 확인하겠습니다. 증인들께서는 모두 자리에서 일어나 주시기 바랍니다. 경기연구원장 나왔습니까? ○ 경기연구원장 임해규 네. ○ 위원장 이재준 경기연구원 부원장 나왔습니까? ○ 부원장 이상훈 네. ○ 위원장 이재준 경영기획본부장 나왔습니까? ○…</p>','경기도의회',false,'{"legacy_id": "audit-9630", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=9630", "page": "https://grilu.kr/gri/audit/9630.html"}'::jsonb,'2016-11-07'::date,'2016-11-07'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-9630');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2015.11.13. 금요일] 경기연구원 — 기획재정위원회 2015년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제9대 경기도의회 기획재정위원회</b> · 2015년도 행정사무감사(2015. 11. 10. ~ 2015. 11. 23.)<br><a href="https://grilu.kr/gri/audit/8822.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=8822" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">2015년도 행정사무감사 기획재정위원회 회의록 경기도의회사무처 피감사기관 : 경기연구원 일 시 : 2015년 11월 13일(금) 장 소 : 경기연구원 회의실 (10시18분 감사개시) ○ 위원장 배수문 좌석을 정돈하여 주시기 바랍니다. 성원이 되었으므로 지금부터 지방자치법 제41조, 동법 시행령 제39조 및 경기도의회 행정사무감사 및 조사에 관한 조례 제2조 규정에 의하여 경기연구원에 대한 2015년도 행정사무감사를 시작하겠습니다. 위원 여러분 그리고 경기연구원 원장을 비롯한 임직원 여러분! 안녕하십니까? 경기도의회 기획재정위원장 배수문 위원입니다. 오늘 감사위원장으로 같이 여러분들과 행감을 진행하게 되었습니다. 오늘은 우리 위원회 감사일정에 따라 경기연구원에 대한 행정사무감사를 실시하게 되었습니다. 여러분도 잘 아시는 바와 같이 지방의회 행정사무감사는 연구원의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 도민의 삶의 질 향상에 기여하고자 함이 목적이므로 매우 중요한 의미가 있다고 하겠습니다. 오늘은 경기도의 싱크탱크인 경기연구원의 운영 실태를 감사하는 것인 만큼 연구원에 대한 심도 있는 감사활동으로 경기도 발전을 위한 정책대안이 제시될 수 있도록 위원 여러분들의 적극적인 감사활동을 부탁드립니다. 아울러 감사에 임하는 원장과 임직원 여러분께서도 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기 바랍니다. 그러면 감사를 시작하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 원장 및 부원장, 본부장, 실장, 부장은 증인의 자격으로 소관 업무를 보고하고 질의에 답변하기에 앞서 먼저 선서하셔야 됩니다. 증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2015년도 행정사무감사를 실시함에 있어 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 한 때에는 지방자치법 제41조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조의 규정에 의하여 고발될 수 있습니다. 또한 증언 또는 진술을 거부한 때에는 동법 규정에 의하여 500만 원 이하의 과태료가 부과될 수 있음을 알려드립니다. 그러면 먼저 증인 출석여부를 확인하겠습니다. 증인들께서는 모두 자리에서 일어나 주시기 바랍니다. 경기연구원장 나왔습니까? ○ 경기연구원장 임해규 네. ○ 위원장 배수문 경기연구원 부원장 나왔습니까? ○ 부원장 이상훈 네. ○ …</p>','경기도의회',false,'{"legacy_id": "audit-8822", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=8822", "page": "https://grilu.kr/gri/audit/8822.html"}'::jsonb,'2015-11-13'::date,'2015-11-13'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-8822');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2014.11.13. 목요일] 경기개발연구원 — 기획재정위원회 2014년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제9대 경기도의회 기획재정위원회</b> · 2014년도 행정사무감사(2014. 11. 11. ~ 2014. 11. 24.)<br><a href="https://grilu.kr/gri/audit/7809.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=7809" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">…겪었습니다. 그런데 한 몇 년 전부터 비로소 서울연구원 수준의 지금 연봉시스템을 이제 갖추어서 조직이 그래도 새로운 연구인력들을 받아들이는 여건을 이제 비로소 갖추었다고 생각합니다. 아마 일전의 신문보도 보셨으면 인천연구원이 굉장히 많은 연구원들이 다 빠져나가서 역량이 축적되지 않고 굉장히 어려움을 겪는다고 들었습니다. 그래서 연구원장들 간에 만나면 이제 경기연구원이 경기도의 위상에 맞게 비로소 연구원의 시스템을 갖춘 걸로 평가를 받고 있는데 그것을 공무원들이 받는 급여하고 비교하는 것은 적절하지 않다고 생각합니다. 우리가 국책연구기관이나 아니면 다른 도책 연구기관, 시ㆍ도책 연구기관들하고 견주어서 저희들이 여러 가지 연구원의 처우를 생각을 해야지 저희들이 안정된 연구기반을 확보할 수 있지 않나 생각합니다. 양해해 주시기 바랍니다. ○ 박재순 위원 잘 들었습니다. 저는 연구비를 꼭 깎아서 그분을 우리 본청하고 구별했다고 생각지는 않습니다. 사람이 꼭 필요한 사람이면 1억이 아니라 10억을 주고라도 모셔 와서 정말 좋은, 훌륭한 연구논문을 가지고 우리 1,250만이 먹고 살 수 있는 그런 인프라가 구성되면 그것처럼 좋은 게 어디 있겠습니까, 이 세상을 살면서, 그죠? 그래서 원장님한테 말씀드리는 것은 꼭 핵심이 있다면 정말 많은 돈을 주고라도 꼭 써야 되지만 그렇지 않은 인력이 있다고 봅니다. 그래서 그런 부분들은 원장님 계시는 동안 충분히 형평성이나 그런 것을 고려해서 잘 해주십사 하는 부탁의 말씀을 드리면서 추후에 다시 질문드리도록 하겠습니다. 이상입니다. ○ 경기개발연구원장 임해규 네, 알겠습니다. (임병택 위원장대리, 배수문 위원장과 사회교대) ○ 위원장 배수문 박재순 위원 수고하셨습니다. 최지용 위원 질의하여 주시기 바랍니다. ○ 최지용 위원 장시간 동안 우리 원장님 수감하시느라 수고 많으십니다. 화성 출신의 최지용 위원입니다. 우리 연구원에서 광역장사시설에 대한 용역을 하셨네요. 장사시설이 절대적으로 부족하다는 것은 우리 도민이나 전 국민이 공감하는 부분인데 다만 화장장에 대한 장사시설이 혐오시설로 인식이 되고 분류됨에 따라서 선뜻 다가가기는 쉽지 않은 시설입니다, 사실. 그러다 보니까 수용하기까지는 많은 갈등과 반목이 반복되다 보니까 어려움을 겪을 수밖에 없습니다. 그래서 우리 연구원에서 연구를 했다는 부분이 어떠한 부분을 연구를 하셨는지, 여기 자료 보면 시민의식조사 실시라고 돼 있는데 그 부분에 …</p>','경기도의회',false,'{"legacy_id": "audit-7809", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=7809", "page": "https://grilu.kr/gri/audit/7809.html"}'::jsonb,'2014-11-13'::date,'2014-11-13'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-7809');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2013.11.15. 금요일] 경기개발연구원 — 기획재정위원회 2013년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제8대 경기도의회 기획재정위원회</b> · 2013년도 행정사무감사(2013. 11. 12. ~ 2013. 11. 25.)<br><a href="https://grilu.kr/gri/audit/7169.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=7169" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">… 경기개발연구원장 홍순영 명칭? ○ 최재우 위원 그렇습니다. ○ 경기개발연구원장 홍순영 저희들이 한번 검토를 쭉 했었고요. 그래서 저희들이 몇 가지 안도 있었습니다. 가장 저희들이 염두에 뒀던 것이 경기발전연구원이었거든요. 경기발전연구원이었는데 이게 정확하게 사단법인 이름으로 이미 등록이 돼 있더라고요. 그래서 그게 무산되고 나니까 여러 가지 정책연구원, 경기연구원 또 다양한 연구원 이름을 했었거든요. 했는데 간단하게 말씀드리면 경기정책연구원, 경기비전연구원, 경기정책전략연구원, 21경기발전연구원, 수도권정책연구원, 한국정책연구원, 경기연구원, 경기개발연구원 쭉 있는데 이게 참 저희들의 상상력의 한계인지는 모르겠습니다만 경기발전연구원, 경기21연구원, 하여튼 이렇게 선정도 했고 다양한 사람들한테 물어보기도 하고 그래서 가장 그래도 괜찮은 것들이 경기발전연구원하고, 저 개인적으로는. 경기연구원하고 이렇게 됐었는데 경기연구원 그러니까 너무 포괄적이어 가지고. 서울 연구원은 서울연구원이란 이름으로 개정도 했지만. 뭔가 그……. 저희 다양한 또 다른 기관도 있는데. 그래서 약간 그런 것도 있고 또 경기발전연구원은 아까도 말씀드린 것과 같이 가장 무난했는데 이미 재빨리, 몇 년 전에 설립했는지 모르겠는데, 경기발전연구원이. 그것도 경기발전연구원이 상당히 오래 전에 이미 사단법인으로 설립이 돼 있어 가지고. 그래서 우리의 아이덴티티를 살리려면 ‘경기’자는 들어가야 되고 말이 길어지면 또 그래서 저희가 지금 경기개발연구원이라고 두고 있는데. 그래서 저희는 어떻게 생각하느냐 하면 개발이라는 게 development인데 development가 반드시 토목 식으로 집 짓고 이러는 것이 아니라 포괄적으로 개념을 생각해서 시대 발전에 맞는 그런 복지연구도 개발이 될 수 있는 거고 복지 개발할 수 있는 것 아니겠습니까? 그래서 이걸 소위 토목 식으로만 생각하지 말자, 개발이라는 말을. 그래서 포괄적으로 생각을 하면 이 명칭 가지고도 충분히, 내용이 문제지. 그래서 그런 식으로 해 가지고 지금 홀딩 상태인데 상황은 그렇습니다. 그래서 저희들이 다양한, 2003년도, 2004년도에도 이 명칭 가지고 문제가 제기된 적이 있고 2011년에도 명칭 가지고 문제된 적이 있는데 그때마다 다양한 명칭을 가지고 이렇게 봤는데 딱 그렇게 눈에 띄고 이러는 것이, 그래서 그 이익이 현재 GRI라고 있는 것을 대체할 수 있는 그 정도의 이익이 되겠는가라는…</p>','경기도의회',false,'{"legacy_id": "audit-7169", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=7169", "page": "https://grilu.kr/gri/audit/7169.html"}'::jsonb,'2013-11-15'::date,'2013-11-15'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-7169');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2012.11.09. 금요일] 경기개발연구원 — 기획위원회 2012년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제8대 경기도의회 기획위원회</b> · 2012년도 행정사무감사(2012. 11. 06. ~ 2012. 11. 19.)<br><a href="https://grilu.kr/gri/audit/1005.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=1005" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">…경기개발연구원장 홍순영 명칭문제요? ○ 배수문 위원 이게 2006년부터 거론됐던 문제인데 아직도 답을 못 내고 있어요? ○ 경기개발연구원장 홍순영 저희들은 준비는 된 상태입니다. 준비는 된 상태고……. ○ 배수문 위원 그럼 올해 안에 결과가 나오겠네요? ○ 경기개발연구원장 홍순영 언제든지 저희들이 요구나, 그런데 솔직히 말씀드리면 저희들이 명칭변경을 하면 경기연구원이 아마 굉장히……. ○ 배수문 위원 유력하다? 본 위원도 그렇게 생각하고요. ○ 경기개발연구원장 홍순영 유력하게 되는데, 저희들이 한, 네? ○ 배수문 위원 서울연구원 때문에 주저하는 거 아닙니까? ○ 경기개발연구원장 홍순영 아닙니다. 그런 건 아니고요. 이게 지금 저희가 이름은 바꿀 필요성이 있으면 바꾸는데, 저희들이 경기연구원으로 바꾸는 데 있어서 큰 문제는 없습니다. 그런데 예산이 몇 억 들고요. 예산이 몇 억 들고. ○ 배수문 위원 자, 본 위원이 지적하는 가장 큰 핵심이 뭐냐면요, 이름을 바꾼다 하면 그 기관의 아이덴티티를 바꾸는 거잖아요? ○ 경기개발연구원장 홍순영 그렇죠. ○ 배수문 위원 그렇기 때문에 중요하고요. 광역 중에서 사실 개발이라는 걸 다 썼어요. 광역단위 연구원에서. 그런데 어느 곳도 지금 쓰고 있지 않고요. 그마만큼 개발이라는 말의 의미가 주는 구태의연함이 있습니다. 인정하시잖아요? ○ 경기개발연구원장 홍순영 네, 인정합니다. ○ 배수문 위원 그래서 GRI로 바꾸신 거는 잘하셨는데 한글로 된 이름도 바꿀 시기가 분명히 왔다. 이거는 동의를 해주셨다고 하니까 빠른 시일 내에 됐으면 좋겠습니다. 이게 작년 행감 때 지적이 됐고요. ○ 경기개발연구원장 홍순영 김현삼 위원장님도 굉장히 관심이 많으셔 가지고 저희가 여러 가지 보고를 드린 바도 있고, 저희들은 레디(Ready)는 돼 있다 이렇게 말씀드리겠습니다. ○ 배수문 위원 알겠습니다. 민선 5기가 후반기로 접어든……. ○ 경기개발연구원장 홍순영 잠깐 얘기하기 전에 아까 서울연구원 말씀을 하셔 가지고 저희들이 또 따라하는 그런 것도 좀 있습니다. ○ 배수문 위원 그래서 지금 말씀드리는 거예요. 그럼에도 불구하고 지금 대안이 서울발전연구원 같은 경우는 이미 언론사에서 선점했잖아요. ○ 경기개발연구원장 홍순영 네. ○ 배수문 위원 그건 뭐 돈 주고 사오기도 그런 시점이잖아요. ○ 경기개발연구원장 홍순영 그래서 그 발전이라는 게, 다른 시도 연구원들이 다 development inst…</p>','경기도의회',false,'{"legacy_id": "audit-1005", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=1005", "page": "https://grilu.kr/gri/audit/1005.html"}'::jsonb,'2012-11-09'::date,'2012-11-09'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-1005');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2011.11.07. 월요일] 경기개발연구원 — 기획위원회 2011년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제8대 경기도의회 기획위원회</b> · 2011년도 행정사무감사(2011. 11. 04. ~ 2011. 11. 17.)<br><a href="https://grilu.kr/gri/audit/1097.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=1097" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">…개발이라고 하는 표현이 과연 지금 이 시대를 제대로 반영하는 용어냐, 제가 이런 주장을 했던 적이 있었는데 우리 원장님 어떻게 생각하십니까? ○ 경기개발연구원장 홍순영 동감입니다. 개발이라는 말 자체가 이게 60년, 70년대식 냄새가 물씬 나고 그래서 저는 예를 들어서 개인적으로는 경기발전연구원이라든지 또는 다른 좋은 말이 있으면 이렇게, 아니면 뭐 그냥 경기연구원이라든지 이런, 아니면 경기지속가능 뭐 하여간 다양한 소위 말하는 21세기에 맞게 했으면 좋겠는데 그런데 이름 바꾸는 일이 이게 쉬운 일이 아니더라구요. 한번 이렇게 정해 놓으면 굉장히 여러, 하여간 쉬운 일이 아니어 가지고……. ○ 김현삼 위원 네, 잘 알겠습니다. 그러니까 이제 명칭을 바꾸는 데서 오는 실무적인 어려움은 있다 하더라도 그러나 기본적으로 제가 말씀드린 명칭을 변경하는 것과 관련된 저의 의견에 대해서는 기본적으로 동의를 하신다 이거죠? ○ 경기개발연구원장 홍순영 네, 100% 동감입니다. 개발이란 말 자체도 뭐……. ○ 김현삼 위원 이를테면 경기발전 또는 경기도정 또는 경기지속가능발전연구센터, 연구원 이렇게 할 수도 있을 것 같습니다. 그러면 제가 한 가지 제안을 드리도록 하겠습니다. 어떤 정책을 수립하거나 또는 그 정책을 뒷받침하기 위한 조례를 제ㆍ개정할 때는 당연하게도 실무적인 뒷받침, 이를테면 예산수반 이런 것들이 같이 검토가 돼야 되겠습니다마는 이 명칭의 변경과 관련돼서 향후에 저희 의회하고 우리 원장님을 중심으로 한 우리 연구원하고 폭넓은 의사소통을 통해서 합리적인 그리고 시대의 어떤 이념을 적절히 담아내는 그런 명칭변경에 대해서 상호 토론을 계속해서 합의를 만들어 나갔으면 좋겠어요. 어떻습니까? ○ 경기개발연구원장 홍순영 네, 좋습니다. ○ 김현삼 위원 네, 고맙습니다. 이상 마치겠습니다. ○ 위원장 강득구 수고하셨습니다. 다음 박승원 위원님. ○ 박승원 위원 원장님, 최근에 서울시의 박원순 시장이 당선되고 나서 제가 들은 얘기입니다마는 서울시청 공무원들이 앞다퉈서 무상급식의 필요성을 막 이렇게 문건을 만들어서 드린다고 그래요. 그전에 오세훈 시장님 계실 때는 무상급식에 대한 반대이론을 막 만들어서 드리고. 이런 현상들에 대해서 어떻게 생각하십니까? ○ 경기개발연구원장 홍순영 저는 사실 공무원 입장에서는 이해가 가는 측면이 있거든요. 일단 시장의 시정을 서포트하는 게 공무원들이고 그런데 시장이 다른 철학을 갖고 왔으면 거기에…</p>','경기도의회',false,'{"legacy_id": "audit-1097", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=1097", "page": "https://grilu.kr/gri/audit/1097.html"}'::jsonb,'2011-11-07'::date,'2011-11-07'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-1097');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2010.11.17. 수요일] 경기개발연구원 — 기획위원회 2010년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제8대 경기도의회 기획위원회</b> · 2010년도 행정사무감사(2010. 11. 15. ~ 2010. 11. 24.)<br><a href="https://grilu.kr/gri/audit/1192.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=1192" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">2010년도 행정사무감사 기획위원회 회의록 경기도의회사무처 피감사기관 : 경기개발연구원 일 시 : 2010년 11월 17일(수) 장 소 : 경기개발연구원회의실 (10시11분 감사개시) ○ 위원장 강득구 좌석을 정돈하여 주시기 바랍니다. 지금부터 지방자치법 제41조, 동법 시행령 제39조 및 경기도의회 행정사무감사 및 조사에 관한 조례 제2조 규정에 의하여 경기개발연구원에 대한 2010년도 행정사무감사를 시작하겠습니다. 위원 여러분 그리고 경기개발연구원 원장을 비롯한 임직원 여러분! 안녕하십니까? 기획위원회 감사위원장 강득구 위원입니다. 오늘은 우리 위원회 감사일정에 따라 경기개발연구원에 대한 행정사무감사를 실시하게 되었습니다. 여러분께서도 잘 아시는 바와 같이 지방의회의 행정사무감사는 연구원의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 2011년도 예산안 심사자료 및 정보획득을 통해 이를 도정시책에 반영하고자 함이 그 목적이므로 매우 중요한 의미가 있다고 할 수 있겠습니다. 따라서 경기도의 싱크탱크인 우리 경기개발연구원의 운영실태를 감사하는 것인 만큼 연구원에 대한 심도 있는 감사활동으로 경기도 발전을 위한 정책대안이 제시될 수 있도록 위원 여러분들의 적극적인 감사활동을 부탁드립니다. 아울러 감사에 임하는 원장과 임직원 여러분께서도 위와 같은 목적이 달성될 수 있도록 적극 협조해 주시기 바랍니다. 경기개발연구원은 제가 알기에는 1995년 3월 20일 날 개원한 것으로 알고 있습니다. 그렇지요? ○ 경기개발연구원장 좌승희 네. ○ 위원장 강득구 벌써 15년의 세월이 흘렀습니다. 공자는 15세에 학문에 뜻을 둔다고 하였습니다. 경기도 발전을 위해 뜻을 둔 경기개발연구원 행정사무감사가 저는 그 의미가 남다르다고 생각합니다. 오늘 행정사무감사가 경기개발연구원의 다음 15년을 내다보는 전환의 발판이 되기를 희망합니다. 그럼 감사를 시작하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 원장 및 부원장, 부장, 센터장은 증인의 자격으로 소관 업무를 보고하고 질의에 답변하기에 앞서 먼저 선서를 하셔야 됩니다. 증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2010년도 행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 할 때에는 지방자치법 제41조제5항 및 경기도의회 행정사무감사 및 …</p>','경기도의회',false,'{"legacy_id": "audit-1192", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=1192", "page": "https://grilu.kr/gri/audit/1192.html"}'::jsonb,'2010-11-17'::date,'2010-11-17'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-1192');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2009.11.17. 화요일] 경기개발연구원 — 기획위원회 2009년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제7대 경기도의회 기획위원회</b> · 2009년도 행정사무감사(2009. 11. 16. ~ 2009. 11. 25.)<br><a href="https://grilu.kr/gri/audit/2254.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=2254" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">2009년도 행정사무감사 기획위원회 회의록 경기도의회사무처 피감사기관 : 경기개발연구원 일 시 : 2009년 11월 17일(화) 장 소 : 경기개발연구원회의실 (10시20분 감사개시) ○ 위원장 김대원 좌석을 정돈해 주시기 바랍니다. 지금부터 지방자치법 제41조, 동법 시행령 제39조 및 경기도의회 행정사무감사 및 조사에 관한 조례 제2조 규정에 의하여 경기개발연구원에 대한 2009년도 행정사무감사를 시작하겠습니다. 위원 여러분 그리고 경기개발연구원 원장을 비롯한 임직원 여러분! 안녕하십니까? 기획위원회 감사위원장 김대원 위원입니다. 오늘 우리 위원회 감사일정에 따라 경기개발연구원에 대한 행정사무감사를 실시하게 되겠습니다. 여러분께서도 잘 아시는 바와 같이 지방의회 행정사무감사는 연구원의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 2010년도 예산안 심사자료 및 정보 획득을 통해 이를 도정시책에 반영하고자 함이 그 목적이므로 매우 중요한 의미가 있다고 할 수 있습니다. 따라서 경기도의 싱크탱크인 경기개발연구원의 운영실태를 감사하는 것인 만큼 연구원에 대한 심도 있는 감사활동으로 경기도의 발전을 위한 정책대안이 제시될 수 있도록 위원 여러분의 적극적인 감사활동을 부탁드립니다. 아울러 감사에 임하는 원장과 임직원 여러분께서도 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기를 부탁드립니다. 끝으로 증인선서에 앞서 한 가지 알려드릴 말씀이 있습니다. 우리 위원회는 감사가 미진할 경우 오는 24일 저희 위원회 회의실에서 해당 부서를 대상으로 종합감사를 실시할 계획입니다. 모쪼록 다시 감사받는 일이 빚어지지 않도록 연구원 원장님과 임직원 여러분께서는 감사에 충실하게 임해 주실 것을 다시 한 번 당부드립니다. 그러면 감사를 시작하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 원장 및 부원장, 부장, 센터장은 증인의 자격으로 소관 업무를 보고하고 질의에 답변하기에 앞서 먼저 선서를 하셔야 합니다. 증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2009년도 행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받고자 하는 것입니다. 만약 증인이 허위증언을 한 때에는 지방자치법 제41조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조의 규정에 의하여 고발될 수 있습니다. 또한 증언 또는 진술을 거부한 때에는 동…</p>','경기도의회',false,'{"legacy_id": "audit-2254", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=2254", "page": "https://grilu.kr/gri/audit/2254.html"}'::jsonb,'2009-11-17'::date,'2009-11-17'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-2254');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2008.11.13. 목요일] 경기개발연구원 — 기획위원회 2008년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제7대 경기도의회 기획위원회</b> · 2008년도 행정사무감사(2008. 11. 12. ~ 2008. 11. 21.)<br><a href="https://grilu.kr/gri/audit/2332.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=2332" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">…김대원 편하실 대로 하십시오. ○ 경기개발연구원장 좌승희 숨바꼭질 하는 것 같아서, 죄송합니다. ○ 고영인 위원 도정시책 기획홍보비를 집행하는 데 있어서 기본적으로 목적과 취지를 어떻게 보고 계십니까? ○ 경기개발연구원장 좌승희 우선 첫째는 경기개발연구원이 하고 있는 사업……. ○ 고영인 위원 간략하게……. ○ 경기개발연구원장 좌승희 사업에 대한 홍보와, 경기연구원을 홍보하는 게 첫 번째겠고요. 그다음에 도정을 같이 홍보하는, 이 두 가지가 제일 중요한 과제라고 생각합니다. ○ 고영인 위원 그러면 경기개발연구원의 전반적인 연구방향에 있어서 그건 맞다고 보고요. 그런데 도정의 홍보에 있어서도 그것이 어떤 객관성을 갖는다든지 또는 공공성을 갖는 커다란 방향에 있어서의 홍보는 어느 정도 맞다고 생각하는데 그 도정의 철학이나 이런 것들이 아직 검증이 안 되고 정책과제 결과가 아직 평가상태에 있는데 그거를 경기개발연구원에서 기획홍보비로 쓸 수가 있나요? ○ 경기개발연구원장 좌승희 이 홍보비를 집행하는 과정은 저희 연구원에 관련된 홍보는 직접적으로 저희가 판단해서 할 수 있지만 도정과 관련된 홍보는 저희가 도청 대변인실하고 긴밀한 협조를 해서, 협의해서 집행하고 있습니다. 그래서 지금 말씀하신 대로 그런 점은 있을 수 있다고 생각합니다. ○ 고영인 위원 자, 그러면 여기 보시죠. 2억 1,450만 원 정도 돼 있는 거죠, 전체 집행액이? ○ 경기개발연구원장 좌승희 네. ○ 고영인 위원 그럼 두 번째 경기국제보트쇼 라디오CM 여기에 약 8,500만 원 가량이 집행이 됐습니다. 그러니까 전체 기획홍보비의 40% 정도가 해당되는데 이것 자체가 경기개발연구원의 공공적 정책방향을 홍보하는 거에 부합하다고 생각하십니까? ○ 경기개발연구원장 좌승희 아시다시피 저희 연구원이 도정을 뒷받침한다고 하는 취지에서 보면 큰 취지에서는 부합한다고 볼 수 있겠지만 좁은 연구라고 하는 의미에서 보면 다소 거리가 있다고 느낄 수도 있지 않을까 하는 생각……. ○ 고영인 위원 바로 그 점이죠. 지금 우리가 보트쇼 문제는 물론 도지사께서 주요한 경기도의 기획사업으로 추진하고 있는데 우리가 앞으로 평가를 통해서 그거의 적합성을 계속적으로 평가하고 비판하면서 대안을 모색해야 되는 과정에 있습니다. 그렇죠? 그런데 올해 추진된 보트쇼의 예산도 지금 몇 차례 언론에 나왔듯이 인원동원 문제라든지, 인원동원도 각 시군단위의 새마을운동협의회나 바르게 살기 이런 데에…</p>','경기도의회',false,'{"legacy_id": "audit-2332", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=2332", "page": "https://grilu.kr/gri/audit/2332.html"}'::jsonb,'2008-11-13'::date,'2008-11-13'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-2332');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2007.11.16. 금요일] 경기개발연구원 — 기획위원회 2007년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제7대 경기도의회 기획위원회</b> · 2007년도 행정사무감사(2007. 11. 13. ~ 2007. 11. 22.)<br><a href="https://grilu.kr/gri/audit/2390.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=2390" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">2007년도 행정사무감사 기획위원회 회의록 제 3 호 경기도의회사무처 피감사기관 : 경기개발연구원 일 시 : 2007년 11월 16일(금) 장 소 : 경개개발연구원회의실 (10시13분 감사개시) ○ 위원장 김영복 좌석을 정돈하여 주시기 바랍니다. 지금부터 지방자치법 제41조, 동법시행령 제39조 및 경기도의회 행정사무감사 및 조사에 관한 조례 제2조의 규정에 의하여 경기개발연구원에 대한 2007년도 행정사무감사를 시작하겠습니다. 위원 여러분 그리고 좌승희 경기개발연구원장을 비롯한 임직원 여러분! 안녕하십니까? 기획위원회 감사위원장 김영복입니다. 지역구 활동과 의정활동을 병행하며 수행하시느라 위원님들 고생이 많으십니다. 오늘은 우리 위원회 감사일정에 따라 경기개발연구원에 대한 행정사무감사를 실시하게 되었습니다. 여러분께서도 잘 아시는 바와 같이 지방의회의 행정사무감사는 연구원의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 2008년도 예산안 심사자료 및 정보 획득을 통해 이를 도정 시책에 반영하고자 함이 그 목적이므로 매우 중요한 의미가 있다고 할 수 있습니다. 따라서 경기도의 싱크탱크인 경기개발연구원의 운영 실태를 감사하는 것인 만큼 연구원에 대한 심도 있는 감사활동으로 경기도 발전을 위한 정책대안이 제시될 수 있도록 위원 여러분들의 적극적인 감사활동을 부탁드립니다. 아울러 감사에 임하는 원장과 임직원 여러분께서도 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기 바랍니다. 그러면 감사를 시작하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 원장 및 부장, 센터장은 증인의 자격으로 소관업무를 보고하고 질의에 답변하기 위해서는 먼저 선서를 하셔야 합니다. 증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2007년도 행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김 없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 한 때에는 지방자치법 제41조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조의 규정에 의하여 고발될 수 있습니다. 또한 증언 또는 진술을 거부한 때에는 동법 규정에 의하여 500만원 이하의 과태료가 부과될 수 있음을 알려드립니다. 그러면 먼저 증인 출석여부를 확인하겠습니다. 피감사기관의 증인은 모두 자리에서 일어서 주시기 바랍니다. 원장 나왔습니까? ○ 경기개발연구원장 좌승희 네. ○ 위원장…</p>','경기도의회',false,'{"legacy_id": "audit-2390", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=2390", "page": "https://grilu.kr/gri/audit/2390.html"}'::jsonb,'2007-11-16'::date,'2007-11-16'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-2390');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2006.11.21. 화요일] 경기개발연구원 — 기획위원회 2006년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제7대 경기도의회 기획위원회</b> · 2006년도 행정사무감사(2006. 11. 20. ~ 2006. 11. 29.)<br><a href="https://grilu.kr/gri/audit/2440.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=2440" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">2006년도 행정사무감사 기획위원회 회의록 제2호 경기도의회사무처 피감사기관 : 경기개발연구원 일 시 : 2006년 11월 21일(화) 장 소 : 경기개발연구원회의실 (10시18분 감사개시) ○ 위원장 김영복 좌석을 정돈하여 주시기 바랍니다. 지금부터 지방자치법 제36조, 동법 시행령 제16조 및 경기도의회 행정사무감사 및 조사에 관한 조례 제2조 규정에 의하여 경기개발연구원에 대한 2006년도 행정사무감사를 시작하겠습니다. 위원 여러분 그리고 경기개발연구원 원장을 비롯한 임직원 여러분! 안녕하십니까? 기획위원회 감사위원장 김영복입니다. 오늘은 우리 위원회 감사일정에 따라 경기개발연구원에 대한 행정사무감사를 실시하게 되었습니다. 여러분께서도 잘 아시는 바와 같이 지방의회 행정사무감사는 연구원의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 2007년도 예산안 심사자료 및 정보획득을 통해 이를 도정시책에 반영하고자 함이 그 목적이므로 매우 중요한 의미가 있다고 할 수 있습니다. 따라서 감사위원 여러분께서는 도민을 대표하여 도비출연기관인 경기개발연구원의 운영실태를 감사하는 것인 만큼 심도있는 감사활동으로 소기의 성과를 거둘 수 있게 되기를 기대하며 아울러 감사에 임하는 원장과 임직원 여러분께서도 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기를 당부드립니다. 그러면 감사를 하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 원장 및 실ㆍ부장은 증인의 자격으로 소관업무를 보고하고 질의에 답변하게 됨으로써 먼저 선서를 하셔야 합니다. 증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2006년도 행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 한 때에는 지방자치법 제36조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조의 규정에 의하여 고발될 수 있으며 증언 또는 진술을 거부한 때에는 동법규정에 의하여 500만원 이하의 과태료가 부과될 수 있음을 알려드립니다. 그러면 먼저 증인 출석여부를 확인하겠습니다. 피감사기관의 증인은 모두 자리에서 일어서 주시기 바랍니다. (일동기립) 원장 나왔습니까? ○ 경기개발연구원장 좌승희 네. ○ 위원장 김영복 부원장 나왔습니까? ○ 경기개발연구원부원장 신원득 네. ○ 위원장 김영복 기획조정실장 나왔습니까? ○ 기획조정실장 이상훈 …</p>','경기도의회',false,'{"legacy_id": "audit-2440", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=2440", "page": "https://grilu.kr/gri/audit/2440.html"}'::jsonb,'2006-11-21'::date,'2006-11-21'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-2440');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2005.11.17. 목요일] 경기개발연구원 — 기획위원회 2005년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제6대 경기도의회 기획위원회</b> · 2005년도 행정사무감사(2005. 11. 17. ~ 2005. 11. 25.)<br><a href="https://grilu.kr/gri/audit/3297.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=3297" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">2005년도 행정사무감사 기획위원회 회의록 제 1 호 경기도의회사무처 피감사기관 : 경기개발연구원 일 시 : 2005년 11월 17일(목) 장 소 : 경기개발연구원회의실 (10시21분 감사개시) ○ 위원장 정인영 좌석을 정돈하여 주시기 바랍니다. 지금부터 지방자치법 제36조, 동법시행령 제16조 및 경기도의회 행정사무감사 및 조사에 관한 조례 제2조 규정에 의하여 경기개발연구원에 대한 2005년도 행정사무감사를 시작하겠습니다. 위원 여러분 그리고 경기개발연구원 부원장을 비롯한 임직원 여러분! 안녕하십니까? 기획위원회 감사위원장 정인영입니다. 오늘은 우리 위원회 감사일정에 따라 경기개발연구원에 대한 행정사무감사를 실시하게 되었습니다. 여러분께서도 잘 아시는 바와 같이 지방의회의 행정사무감사는 연구원의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 2006년도 예산안 심사자료 및 정보획득을 통해 이를 도정시책에 반영하고자 함이 그 목적이므로 매우 중요한 의미가 있다 할 수 있습니다. 따라서 감사위원 여러분께서는 도민을 대표하여 도비 출연기관인 경기개발연구원의 운영실태를 감사하는 것인 만큼 심도있는 감사활동으로 소기의 성과를 거둘 수 있게 되기를 기대합니다. 아울러 감사에 임하는 위원장과 임직원 여러분께서도 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기를 당부드립니다. 그러면 감사를 하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 부원장 및 실ㆍ부장은 증인의 자격으로 소관업무를 보고하고 질의에 답변하게 됨으로써 먼저 선서를 하셔야 합니다. 증인선서의 취지와 관계 규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2005년도 행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 한 때에는 지방자치법 제36조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조의 규정에 의하여 고발될 수 있으며 증언 또는 진술을 거부한 때에는 동법규정에 의하여 500만원 이하의 과태료가 부과될 수 있음을 알려드립니다. 그러면 먼저 증인 출석여부를 확인하겠습니다. 피감사기관의 증인은 모두 자리에서 일어서 주시기 바랍니다. (일동기립) 부원장 나왔습니까? ○ 경기개발연구원부원장 김태승 네. ○ 위원장 정인영 기획조정실장 나왔습니까? ○ 기획조정실장 성현찬 네. ○ 위원장 정인영 사무처장 나왔습니까? ○ 사무처…</p>','경기도의회',false,'{"legacy_id": "audit-3297", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=3297", "page": "https://grilu.kr/gri/audit/3297.html"}'::jsonb,'2005-11-17'::date,'2005-11-17'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-3297');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2004.11.26. 금요일] 경기개발연구원 — 기획위원회 2004년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제6대 경기도의회 기획위원회</b> · 2004년도 행정사무감사(2004. 11. 22. ~ 2004. 12. 01.)<br><a href="https://grilu.kr/gri/audit/3351.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=3351" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">2004년도 행정사무감사 기획위원회 회의록 제5호 경기도의회사무처 피감사기관 : 경기개발연구원 일 시 : 2004년 11월 26일(금) 장 소 : 경기개발연구원회의실 (10시50분 감사개시) ○ 위원장 정인영 좌석을 정돈하여 주시기 바랍니다. 지금부터 지방자치법 제36조, 동법시행령 제16조 및 경기도의회행정사무감사및조사에관한조례 제2조의 규정에 의하여 경기개발연구원에 대한 2004년도 행정사무감사를 시작하겠습니다. 위원 여러분 그리고 경기개발연구원장을 비롯한 임직원 여러분! 안녕하십니까? 기획위원회 감사위원장 정인영입니다. 오늘은 우리 위원회 감사일정에 따라 경기개발연구원에 대한 행정사무감사를 실시하게 되었습니다. 여러분께서도 잘 아시는 바와 같이 지방의회의 행정사무감사는 연구원의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 2005년도 예산안 심사자료 및 정보 획득을 통해 이를 도정시책에 반영하고자 함이 그 목적이므로 매우 중요한 의미가 있다고 할 수 있습니다. 따라서 감사위원 여러분께서는 연일 계속되는 감사일정으로 노고가 많으십니다만 도민을 대표하여 도비 출연기관인 경기개발연구원의 운영실태를 감사하는 것이니만큼 심도 있는 감사활동으로 소기의 성과를 거둘 수 있게 되기를 기대하면서 아울러 감사에 임하는 연구원 원장님과 임직원 여러분께서도 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기를 당부드립니다. 그러면 감사를 하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 경기개발연구원장 및 실ㆍ부장은 증인의 자격으로 소관 업무를 보고하고 질의에 답변하게 됨으로써 먼저 선서를 하셔야 합니다. 증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2004년도 행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약, 증인이 허위증언을 한 때에는 지방자치법 제36조제5항 및 경기도의회행정사무감사및조사에관한조례 제30조의 규정에 의하여 고발될 수 있으며 증언 또는 진술을 거부한 때에는 동법 규정에 의하여 500만원이하의 과태료가 부과될 수 있음을 알려드립니다. 그러면 먼저 증인출석 여부를 확인하겠습니다. 피감사기관의 증인은 모두 자리에서 일어서 주시기 바랍니다. 경기개발연구원장 나왔습니까? ○ 경기개발연구원장 한현규 네. ○ 위원장 정인영 기획조정실장 나왔습니까? ○ 기획조정실장 신원득 네. ○ 위원장 정…</p>','경기도의회',false,'{"legacy_id": "audit-3351", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=3351", "page": "https://grilu.kr/gri/audit/3351.html"}'::jsonb,'2004-11-26'::date,'2004-11-26'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-3351');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2003.11.26. 수요일] 경기개발연구원 — 기획위원회 2003년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제6대 경기도의회 기획위원회</b> · 2003년도 행정사무감사(2003. 11. 21. ~ 2003. 11. 28.)<br><a href="https://grilu.kr/gri/audit/3401.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=3401" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">…습니다. 총 190건의 사업량을 계획하고 있습니다. 이 중에서 연구과제 사업으로써 우선 기본연구과제는 28개 과제를 계획하고 있고 그 다음에 수탁연구과제는 40과제 이것은 부서당 8개 과제를 수행하는 것을 목표로 설정했습니다. 정책연구과제는 55개 과제입니다. 그리고 위탁연구과제와 지역연구과제를 우선적으로 했습니다. 다음은 정기간행물 사업입니다. 그 동안 경기연구원은 연간으로 발행을 하면서 추진했습니다마는 실효성 문제를 저희들이 검토를 해서 이것을 연 4회 발행하는 경기논단과 통합을 해서 특집주제 중심으로 발행할 예정에 있습니다. 또한 KRI 뉴스레터를 발행할 예정이고 경기도 경제동향과 전망, 이것은 월간이 되겠습니다. 경기도 경제동향과 전망은 맨 밑에 보시면 알기 쉬운 경기도경제지표를 통합해서 조금더 효율적인 간행물을 관리를 할 예정에 있습니다. 또한 연구원 안내책자 브로셔를 발행할 예정입니다. 연구조성사업은 총 27건 그리고 기타 통합정보시스템, GIS 실험실 1시·군 1담당제 정책포럼 등을 운영할 예정입니다. 19쪽부터는 기본연구사업에 대한 구체적인 사항이 되겠습니다. 우선 기본연구과제는 보시는 바와 같이 20쪽에 10개 과제가 소개가 되어 있습니다마는 현재 자료 제출한 시점하고 현재의 시점이 차이가 있어서 총 14개 과제가 연구위원회를 통과한 상태다 이렇게 말씀드리도록 하겠습니다. 다음에 세부연구사업 계획은 21쪽부터 25쪽 기본과제에 대한 구체적인 과제명, 그 다음에 연구목적과 내용, 그리고 기대효과 등으로 정리가 되어 있습니다. 이것은 자료로 갈음하도록 하겠습니다. 다음은 26쪽의 수탁연구과제가 되겠습니다. 수탁연구과제는 외부기관에서 경기개발연구원에 용역을 의뢰한 과제가 되겠습니다. 그래서 이것은 앞으로 추진방향은 재정자립도의 제고뿐만 아니라 여러 가지 목적을 위해서 적극적으로 수행을 해야 되겠다 라고 하는 것이고 일정금액 이하의 용역 수행절차를 간소화해서 일부 시·군에서 상당히 중요한 과제임에도 불구하고 금액이 적다라든지 절차가 복잡해서 수행하는데 소극적인 이런 것을 해소하고자 합니다. 사업계획은 1개 부서당 총 8건으로 해서 40개 과제를 수행할 예정입니다. 다음은 27쪽 정책연구과제가 되겠습니다. 앞에서 소개해 드린 바와 같이 경기도로부터 긴급 요청된 시의성 있는 현안문제하고 연구원 자체적으로 이 문제가 다뤄져야 되겠다라고 판단하는 과제가 되겠습니다. 또한 여기에는 CEO리포트도 포함이 돼서 앞…</p>','경기도의회',false,'{"legacy_id": "audit-3401", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=3401", "page": "https://grilu.kr/gri/audit/3401.html"}'::jsonb,'2003-11-26'::date,'2003-11-26'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-3401');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2002.11.26. 화요일] 경기개발연구원 — 기획위원회 2002년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제6대 경기도의회 기획위원회</b> · 2002년도 행정사무감사(2002. 11. 21. ~ 2002. 11. 30.)<br><a href="https://grilu.kr/gri/audit/3446.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=3446" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">2002년도 행정사무감사 기획위원회 회의록 제4호 경기도의회사무처 피감사기관 : 경기개발연구원 일 시 : 2002년 11월 26일(화) 장 소 : 경기개발연구원 (10시16분 감사개시) ○ 위원장대리 이원재 좌석을 정돈해 주시기 바랍니다. 지금부터 지방자치법 제36조, 동법시행령 제16조 및 경기도의회행정사무감사및조사에관한조례 제2조 규정에 의해서 경기개발연구원에 대한 2002년도 행정사무감사 실시를 선언합니다. 위원 여러분 그리고 연구원장을 비롯한 임직원 여러분! 안녕하십니까? 기획위원회 유영록 위원장님의 감사를 대신한 이원재 위원입니다. 오늘부터 우리 위원회 감사일정에 따라 경기개발연구원에 대한 행정사무감사를 실시하게 되었습니다. 여러분께서도 잘 아시는 바와 같이 지방의회 행정사무감사는 연구원의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 2003년도 예산안 심사자료 및 정보획득을 통해서 이를 도정시책에 반영하고자 함이 그 목적이므로 매우 중요한 의미가 있다고 하겠습니다. 따라서 감사위원 여러분들께서는 연일 계속되는 감사일정에 노고가 많으십니다만 도민을 대표해서 도비 출연기관인 경기개발연구원의 운영실태를 감사하는 것이니 만큼 심도있는 감사활동으로 소기의 성과를 거둘 수 있게 하여 주시기를 기대하면서 아울러 감사에 임하는 연구원장님을 비롯한 임직원께서도 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기를 당부드립니다. 그러면 감사를 하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 연구원장 및 실·부장은 증인자격으로 소관업무를 보고하고 답변을 하게 됨으로써 먼저 선서를 하셔야 합니다. 증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2002년도 행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 할 때에는 지방자치법 제36조제5항 및 경기도의회행정사무감사및조사에관한조례 제8조 규정에 의하여 고발될 수 있으며 증언 또는 진술을 거부할 때는 동법 규정에 의하여 500만원 이하의 과태료가 부과될 수 있음을 알려드립니다. 그러면 피감사기관의 증인은 모두 자리에 일어서 주시기 바랍니다. (일동기립) 먼저 증인출석여부를 확인하겠습니다. 경기개발연구원장 나오셨습니까? ○ 경기개발연구원장 이철규 네. ○ 위원장대리 이원재 사무처장 나오셨습니까? ○ 사무처장 김봉규 네. ○ 위원장대…</p>','경기도의회',false,'{"legacy_id": "audit-3446", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=3446", "page": "https://grilu.kr/gri/audit/3446.html"}'::jsonb,'2002-11-26'::date,'2002-11-26'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-3446');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2001.11.26. 월요일] 경기개발연구원, 감사관실 — 기획위원회 2001년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제5대 경기도의회 기획위원회</b> · 2001년도 행정사무감사(2001. 11. 21. ~ 2001. 11. 30.)<br><a href="https://grilu.kr/gri/audit/4588.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=4588" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">2001년도 행정사무감사 기획위원회 회의록 제4호 경기도의회사무처 피감사기관 : 경기개발연구원, 감사관실 일 시 : 2001년 11월 26일(월) 장 소 : 경기개발연구원회의실, 기획위원회 (10시38분 감사개시) ○ 위원장 김강선 좌석을 정돈하여 주시기 바랍니다. 지금부터 지방자치법 제36조, 동법시행령 제16조 및 경기도의회행정사무감사및조사에관한조례 제2조 규정에 의하여 경기개발연구원에 대한 2001년도 행정사무감사 실시를 선언합니다. 위원 여러분! 그리고 원장님을 비롯한 연구원 임직원 여러분! 안녕하십니까? 기획위원회 감사위원장 김강선입니다. 오늘은 우리 위원회 감사일정에 따라서 경기개발연구원에 대한 행정사무감사를 실시하게 되었습니다. 연일 계속되는 감사일정으로 노고가 많으신 위원님들께 심심한 위로와 감사의 말씀을 드리며 도민을 대표하여 도비출연기관인 경기개발연구원의 운영실태를 감사하는 것인 만큼 심도있는 감사가 이루어질 수 있도록 위원 여러분의 적극적인 의정활동을 당부드립니다. 아울러 수감준비를 위하여 애쓰신 연구원 임직원 여러분께도 감사와 격려의 말씀을 드립니다. 그러면 감사를 하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 경기개발연구원장 및 실부장은 증인의 자격으로 소관업무를 보고하고 질의에 답변하게 됨으로써 먼저 선서를 하셔야 합니다. 증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2001년도 행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 한 때에는 지방자치법 제36조제5항 및 경기도의회행정사무감사및조사에관한조례 제30조의 규정에 의하여 고발될 수 있으며 증언 또는 진술을 거부한 때에는 동법 규정에 의하여 500만원이하의 과태료가 부과될 수 있음을 알려드립니다. 그러면 피감사기관의 증인은 모두 자리에서 일어서 주시기 바랍니다. (기 립) 먼저 증인 출석여부를 확인하겠습니다. 경기개발연구원장 나오셨습니까? ○ 경기개발연구원장 노춘희 네. ○ 위원장 김강선 사무처장 나왔습니까? ○ 사무처장 유지준 네. ○ 위원장 김강선 기획조정실장 나왔습니까? ○ 기획조정실장 조응래 네. ○ 위원장 김강선 도시경영연구부장 나왔습니까? ○ 도시경영연구부장 김동성 네, 나왔습니다. ○ 위원장 김강선 도시지역계획부장 나왔습니까? ○ 도시지역계획부장 이상대 네. ○ 위원장 김강선 교통정책연구부장 …</p>','경기도의회',false,'{"legacy_id": "audit-4588", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=4588", "page": "https://grilu.kr/gri/audit/4588.html"}'::jsonb,'2001-11-26'::date,'2001-11-26'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-4588');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2000.11.23. 목요일] 경기개발연구원 — 기획위원회 2000년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제5대 경기도의회 기획위원회</b> · 2000년도 행정사무감사(2000. 11. 21. ~ 2000. 11. 30.)<br><a href="https://grilu.kr/gri/audit/4643.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=4643" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">2000년도 행정사무감사 기획위원회 회의록 제3호 경기도의회사무처 피감사기관 : 경기개발연구원 일 시 : 2000년 11월 23일(목) 장 소 : 경기개발연구원회의실 (10시35분 감사개시) ○ 위원장 김강선 좌석을 정돈하여 주시기 바랍니다. 지금부터 지방자치법 제36조, 동법시행령 제16조 및 경기도의회행정사무감사및조사에관한조례 제2조 규정에 의하여 경기개발연구원에 대한 2000년도 행정사무감사 실시를 선언합니다. 위원 여러분 그리고 연구원 임직원 여러분! 안녕하십니까? 기획위원회 감사위원장 김강선입니다. 오늘은 기획위원회 감사일정에 따라서 경기개발연구원에 대한 행정사무감사를 실시하게 되었습니다. 여러분께서도 잘 아시는 바와 같이 지방의회 행정사무감사는 연구원의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 2001년도 예산안 심사를 위한 자료로 활용하며 아울러 이를 도정시책에 반영하고자 함이 그 목적인 만큼 감사에 임하는 연구원 원장님과 임직원 여러분께서는 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기를 바랍니다. 감사위원 여러분께서도 연일 계속되는 감사일정으로 노고가 많으십니다마는 도민을 대표하여 도비 출연기관인 경기개발연구원의 운영실태를 감사하는 것이니 만큼 각 부문별로 심도있게 질의하시어 소기의 성과를 거둘 수 있게 되기를 당부드리면서 원활한 감사진행을 위하여 많은 협조가 있으시기를 바라겠습니다. 끝으로 행정사무감사 준비를 위하여 애써 주신 연구원 임직원 여러분께도 감사와 격려의 말씀을 드립니다. 그러면 감사를 하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 경기개발연구원장 및 실·부장은 증인의 자격으로 소관업무를 보고하고 질의에 답변하게 됨으로써 먼저 선서를 하셔야 합니다. 증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2000년도 행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 한 때에는 지방자치법 제36조제5항 및 경기도의회행정사무감사및조사에관한조례 제30조의 규정에 의하여 고발될 수 있으며 증언 또는 진술을 거부한 때에는 동법 규정에 의하여 500만원이하의 과태료가 부과될 수 있음을 알러드립니다. 그러면 피감사기관의 증인은 모두 자리에서 일어서 주시기 바랍니다. (기 립) 먼저 증인출석 여부를 확인하겠습니다. 경기개발연구원장 나오셨습니까? ○ …</p>','경기도의회',false,'{"legacy_id": "audit-4643", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=4643", "page": "https://grilu.kr/gri/audit/4643.html"}'::jsonb,'2000-11-23'::date,'2000-11-23'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-4643');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[1999.11.27. 토요일] 경기개발연구원 — 기획위원회 1999년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제5대 경기도의회 기획위원회</b> · 1999년도 행정사무감사(1999. 11. 22. ~ 1999. 12. 01.)<br><a href="https://grilu.kr/gri/audit/4701.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=4701" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">1999년도 행정사무감사 기획위원회 회의록 제6호 경기도의회사무처 피감사기관 : 경기개발연구원 일 시 : 1999년 11월 27일(토) 장 소 : 경기개발연구원회의실 (10시50분 감사개시) ○ 위원장 고수복 좌석을 정돈해 주시기 바랍니다. 지금부터 지방자치법 제36조, 동법시행령 제16조 및 경기도의회행정사무감사및조사에관한조례에 의하여 경기개발연구 원에 대한 1999년도 행정사무감사를 실시할 것을 선언합니다. 위원 여러분, 그리고 연구원의 임직원 여러분! 안녕하십니까? 기획위원장 고수복 위원입니다. 오늘은 기획위원회 감사일정에 따라서 경기개발연구원에 대한 행정사무 감사를 실시하게 되었습니다. 여러분께서도 잘 아시는 바와 같이 지방의회 행정사무감사는 연구원의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 2000년도 예산안 심사를 위한 자료로 활용하며 아울러 이를 도정시책에 반영하고자 함이 그 목적인 만큼 감사에 임하는 연구원 원장님과 임직원 여러분께서는 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기 바랍니다. 감사 위원 여러분께서도 연일 계속되는 감사 일정으로 노고가 많으십니다만 도민을 대표하여 도비출연기관인 경기개발연구원의 운영실태를 감사하는 것이니만큼 각 부분별로 세밀하게 검토하셔서 소기의 성과를 거둘 수 있게 되기를 당부드리면서 원활한 감사진행을 위하여 많은 협조있으시기 바라겠습니다. 끝으로 행정사무감사 준비를 위하여 애쓰신 연구원 임직원 여러분께도 감사와 격려의 말씀을 드립니다. 그러면 감사를 하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 경기개발연구원장은 증인의 자격으로 소관업무를 보고하고 질의에 답변하게 됨으로써 먼저 선서를 하셔야 합니다. 증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 1999년도 행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 한 때에는 지방자치법 제36조제5항 및 경기도의회행정사무감사및조사에관한조례 제30조의 규정에 의하여 고발될 수 있으며 증언 또는 진술을 거부한 때에는 동법 동조항의 규정에 의하여 500만원이하의 과태료를 부과할 수 있음을 알려드립니다. 그러면 피감사기관의 증인은 모두 자리에서 일어서 주시기 바랍니다. 먼저 증인출석 여부를 확인하겠습니다. 경기개발연구원장 나오셨습니까? ○ 경기개발연구원장 노춘희 네. ○ …</p>','경기도의회',false,'{"legacy_id": "audit-4701", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=4701", "page": "https://grilu.kr/gri/audit/4701.html"}'::jsonb,'1999-11-27'::date,'1999-11-27'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-4701');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[1998.11.26. 목요일] 경기개발연구원, 경기지방공사 — 기획위원회 1998년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제5대 경기도의회 기획위원회</b> · 1998년도 행정사무감사(1998. 11. 21. ~ 1998. 11. 30.)<br><a href="https://grilu.kr/gri/audit/4757.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=4757" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">1998년도 행정사무감사 기획위원회 회의록 제5호 경기도의회사무처 피감사기관 : 경기개발연구원, 경기지방공사 일 시 : 1998년 11월 26일(목) 장 소 : 경기개발연구원회의실, 경기지방공사회의실 (10시35분 감사개시) ○ 위원장 고수복 좌석을 정돈해 주시기 바랍니다. 지금부터 지방자치법제36조, 동법시행령제16조와 경기도의회행정사무감사및조사에관한조례에 의하여 경기개발연구원에 대한 1998년도 행정사무감사 실시를 선언합니다. 안녕하십니까? 기획위원장 고수복 위원입니다. 오늘은 기획위원회 감사일정에 따라서 경기개발연구원에 대한 행정사무감사를 실시하게 되었습니다. 여러분께서도 잘 아시는 바와 같이 지방의회 행정사무감사는 집행부의 행정사무 전반에 관한 실태를 파악하여 지방의회 의정활동과 &#x27;99년도 예산안 심사시 활용하며 아울러 이를 도정시책에 반영하고자 함이 그 목적인 만큼 감사에 임하는 연구원 원장님과 임직원 여러분께서는 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기 바랍니다. 감사위원 여러분께서도 연일 계속되는 감사일정으로 노고가 많으십니다만 도민을 대표하여 도비 출연기관인 경기개발연구원의 운영실태를 감사하는 것이니 만큼 각 부분별로 세밀하게 검토하시어 소기의 성과를 거둘 수 있기를 당부드리면서 원활한 감사진행을 위하여 많은 협조 있으시기를 바랍니다. 끝으로 행정사무감사 준비를 위하여 애쓰신 연구원 관계직원 여러분께 감사드리며 간단히 인사에 갈음합니다. 그러면 감사를 하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 경기개발연구원장은 증인의 자격으로 소관업무를 보고하고 질의에 답변하게 되므로 먼저 선서를 하셔야 하며 증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 1998년도행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 할 때에는 지방자치법제36조제5항과 경기도의회행정사무감사및조사에관한조례제30조의 규정에 의하여 고발될 수 있으며 증언 또는 진술을 거부할 때에는 동법동조항규정에 의하여 500만원 이하의 과태료를 부과할 수 있음을 알려드립니다. 그러면 피감사기관의 증인은 모두 자리에서 일어서 주시기 바랍니다. (기 립) 먼저 증인출석 여부를 확인하겠습니다. 경기개발연구원장 나왔습니까? ○ 경기개발연구원장 유훈 네. ○ 위원장 고수복 사무처장 나왔습니까? ○ 사무처장 표찬섭 네.…</p>','경기도의회',false,'{"legacy_id": "audit-4757", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=4757", "page": "https://grilu.kr/gri/audit/4757.html"}'::jsonb,'1998-11-26'::date,'1998-11-26'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-4757');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[1997.11.29. 토요일] 경기개발연구원 — 기획위원회 1997년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제4대 경기도의회 기획위원회</b> · 1997년도 행정사무감사(1997. 11. 21. ~ 1997. 11. 29.)<br><a href="https://grilu.kr/gri/audit/5589.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=5589" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">1997년도 행정사무감사 기획위원회 회의록 제8호 경기도의회사무처 피감사기관 : 경기개발연구원 일 시 : 1997년 11월 29일(토) 장 소 : 경기개발연구원회의실 (10시35분 감사개시) ○ 위원장 박영하 좌석을 정돈해 주시기 바랍니다. 지금부터 지방자치법제36조, 동법시행령제16조와 경기도의회행정사무감사및조사에관한조례에 의하여 경기개발연구원에 대한 1997년도행정사무감사 실시할 것을 선언합니다. 기획위원회 위원장 박영하 위원입니다. 오늘은 기획위원회 감사일정에 따라서 경기개발연구원에 대한 행정사무감사를 실시하게 되었습니다. 여러분께서도 잘 아시는 바와 같이 지방의회 행정사무감사는 집행부의 행정사무 전반에 관한 실태를 파악하여 지방의회 의정활동과 &#x27;98년도 예산안 심사시 활용하며 아울러 이를 도정시책에 반영하고자 함이 그 목적인 만큼 감사에 임하는 연구원 원장님과 임직원 여러분께서는 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기 바랍니다. 감사위원 여러분께서도 아침 일찍부터 행정사무감사에 임하시기 위하여 비가 오는 데도 불구하시고 먼 곳에서 오시느라고 수고가 많으셨습니다. 도민을 대표하여 도비출연기관인 경기개발연구원의 운영실태를 감사하는 것이니 만큼 각 부분별로 세밀하게 검토하시어 소기의 성과를 거둘 수 있기를 당부드리면서 원활한 감사진행을 위하여 많은 협조 있으시기를 바랍니다. 끝으로 행정사무감사 준비를 위하여 애쓰신 연구원 관계 직원 여러분께 감사를 드리며 간단히 인사에 갈음합니다. 감사합니다. 그러면 감사를 하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 경기개발연구원장은 증인의 자격으로 소관 업무를 보고하고 질의에 답변하게 됨으로써 먼저 선서를 하셔야 하며 증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 1997년도행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 할 때에는 지방자치법제36조제5항과 경기도의회행정사무감사및조사에관한조례제30조의 규정에 의하여 고발될 수 있으며 증언 또는 진술을 거부할 때에는 같은 법시행령제17조의4제4항 규정에 의하여 500만원 이하의 과태료를 부과할 수 있음을 알려드립니다. 그러면 피감사기관의 증인은 모두 자리에서 일어서 주시기 바랍니다. (기 립) 먼저 증인출석여부를 확인하겠습니다. 경기개발연구원장님 나오셨습니까? ○ 경기개발연구원장 …</p>','경기도의회',false,'{"legacy_id": "audit-5589", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=5589", "page": "https://grilu.kr/gri/audit/5589.html"}'::jsonb,'1997-11-29'::date,'1997-11-29'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-5589');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[1996.11.29. 금요일] 경기개발연구원 — 기획위원회 1996년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제4대 경기도의회 기획위원회</b> · 1996년도 행정사무감사(1996. 11. 21. ~ 1996. 11. 30.)<br><a href="https://grilu.kr/gri/audit/5638.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=5638" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">1996년도 행정사무감사 기획위원회 회의록 제8호 경기도의회사무처 피감사기관 : 경기개발연구원 일 시 : 1996년 11월 29일(금) 장 소 : 경기개발연구원회의실 (10시30분 감사개시) ○ 위원장 이광길 좌석을 정돈해 주시기 바랍니다. 지금부터 지방자치법 제36조동법시행령 제16조 및 경기도의회행정사무감사및조사에관한조례에 의하여 경기개발연구원에 대한 1996년도 행정사무감사를 실시할 것을 선언합니다. 안녕하십니까? 기획위원장 이광길 위원입니다. 오늘은 기획위원회 감사일정에 따라 경기개발연구원에 대한 행정사무감사를 실시하게 되었습니다. 여러분께서도 잘 아시는 바와 같이 지방의회 행정사무감사는 집행부의 행정사무 전반에 관한 실태를 파악하여 지방의회의 의정활동과 &#x27;97년도 예산안 심사시 활용하며 아울러 이를 도정시책에 반영하고자함이 그 주요목적인 만큼 감사에 임하는 연구원 원장님과 임직원 여러분께서는 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기 바랍니다. 또한 감사위원 여러분께서도 아침 일찍부터 행정사무감사에 임하시기 위하여 먼곳에서 오시느라 노고가 많으셨습니다. 도민을 대표하여 도비출연기관인 경기개발연구원의 운영실태를 감사하는 것이니 만큼 각 부분별로 세밀하게 검토를 하여 소기의 성과를 거둘 수 있기를 당부 드리면서 원활한 감사진행을 위하여 많은 협조가 있으시기를 바라겠습니다. 끝으로 행정사무감사 준비를 위하여 애쓰신 연구원 관계직원 여러분께 감사를 드리며 간단하게 인사를 갈음하겠습니다. 그러면 감사를 하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 경기개발연구원장은 증인의 자격으로 소관업무를 보고하고 질의에 답변하게 됨으로써 먼저 선서를 하셔야 됩니다. 증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 1996년도행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 할 때는 지방자치법제36조제5항 및 경기도의회행정사무감사및조사에관한조례 제30조의 규정에 의하여 고발될 수 있으며 증언 또는 진술을 거부할 때에는 같은법시행령 제17조의4제4항 및 경기도의회행정사무감사및조사에관한조례 제31조의 규정에 의하여 과태료를 부과할 수 있음을 알려드립니다. 그러면 피감사기관의 증인은 모두 자리에서 일어나 주시기 바랍니다. (기 립) 먼저 증인출석여부를 확인하겠습니다. 경기개발연구원장님 나오셨습니…</p>','경기도의회',false,'{"legacy_id": "audit-5638", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=5638", "page": "https://grilu.kr/gri/audit/5638.html"}'::jsonb,'1996-11-29'::date,'1996-11-29'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-5638');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[1995.11.28. 화요일] 경기개발연구원 — 기획위원회 1995년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제4대 경기도의회 기획위원회</b> · 1995년도 행정사무감사(1995. 11. 21. ~ 1995. 11. 28.)<br><a href="https://grilu.kr/gri/audit/5692.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 회의록 전문 보기</a> &nbsp;|&nbsp; <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=5692" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 원문</a></div><p style="line-height:1.8;color:#444">1995년도 행정사무감사 기획위원회 회의록 제7호 경기도의회사무처 피감사기관 : 경기개발연구원 일 시 : 1995년 11월 28일(화) 장 소 : 경기개발연구원회의실 (10시 16분 감사개시) ○ 위원장 이광길 자리를 정돈해 주시기 바랍니다. 지금부터 지방자치법 제36조, 동법시행령 제16조 및 경기도의회행정사무감사및조사에관한조례에 의하여 경기개발연구원에 대한 1995년도행정사무감사를 실시할 것을 선언합니다. 안녕하십니까? 기획위원장 이광길 위원입니다. 과거가 있어 현재가 있으며 현재보다는 미래를 위하여 열심히 생활하듯이 경기도의 복지건설과 도민의 질 높은 삶을 위하여 연구하시는 경기개발연구원 원장님을 비롯한 관계직원 여러분, 여러분들의 아낌 없는 노력과 봉사는 경기도민의 희망입니다. 아무쪼록 일등경기, 세계 속의 경기도가 되는 데 열과 성을 다해주시기 바랍니다. 우리 750만 도민은 여러분들의 일거수일투족을 직시하며 격려를 아끼지 않을 것입니다. 오늘 기획위원회 감사일정에 따라서 경기개발연구원에 대한 행정사무감사를 실시하게 되었습니다. 여러분께서도 잘 아시는 바와 같이 지방의회 행정사무감사는 집행부의 행정사무 전반에 관한 실태를 파악하여 지방의회의 의정활동과 &#x27;96년도예산 심의시 활용하며 아울러 이를 도정시책에 반영하고자 함이 그 목적인 만큼 감사에 임하는 연구원 관계관 여러분께서는 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기 바랍니다. 또한 감사위원 여러분께서도 행정사무감사에 임하시기 위하여 먼 곳에서 오시느라고 수고가 많으셨습니다. 도민을 대표하여 도비출연기관인 경기개발연구원의 운영실태를 감사하는 것이니 만큼 각 부분별로 세밀하게 검토하시어 소기의 성과를 거둘 수 있기를 당부드리면서 원활한 감사진행을 위하여 많은 협조가 있으시기를 바랍니다. 끝으로 행정사무감사 준비를 위하여 애쓰신 연구원 관계직원 여러분께 감사드리며 간단히 인사에 갈음합니다. 그러면 감사를 하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 관계 부서장은 증인의 자격으로 소관업무를 보고하고 질의에 답하게 되므로 먼저 선서를 하셔야 합니다. 증인선서의 취지와 관계규정을 말씀드리면, 선서를 하는 이유는 이번에 경기도의회가 1995년도행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 할 때에는 지방자치법 제36조제5항의 규정에 의하여 고발될 수 …</p>','경기도의회',false,'{"legacy_id": "audit-5692", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=5692", "page": "https://grilu.kr/gri/audit/5692.html"}'::jsonb,'1995-11-28'::date,'1995-11-28'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-5692');